package dev.veltraph.client.rotation;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class NormalIdleCancellationIdentityTest {
 final Object install=new Object(),provider=new Object(),token=new Object(),root=new Object(),parent=new Object(),player=new Object(),world=new Object(),connection=new Object(),store=new Object(),service=new Object(),options=new Object(),hardware=new Object();
 NormalIdleCancellationIdentity.Scope s(long e,long g,long serial,long ticket,boolean normal,boolean current,boolean ready,boolean none,Object hardware){return new NormalIdleCancellationIdentity.Scope(install,provider,token,root,parent,player,world,connection,store,service,options,hardware,2,g,e,serial,ticket,normal,current,ready,none);}
 NormalIdleCancellationIdentity.Scope before(){return s(8,5,4,4,true,true,true,true,hardware);}
 @Test void actualTickAndFrameSingleCancelEvidenceCanAdvanceOneEpoch(){for(var site:NormalIdleCancellationIdentity.Site.values())assertTrue(NormalIdleCancellationIdentity.transition(before(),s(9,5,4,4,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,site));}
 @Test void nullScopeForEveryOtherCauseCannotCertify(){for(var cause:NormalIdleCancellationIdentity.Cause.values())if(cause!=NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER)assertFalse(NormalIdleCancellationIdentity.transition(before(),s(9,5,4,4,true,true,true,true,hardware),cause,NormalIdleCancellationIdentity.Site.BEFORE_TICK));}
 @Test void pendingManualCanceledOrRevokedNormalCannotCertify(){assertFalse(NormalIdleCancellationIdentity.eligible(s(8,5,4,4,false,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER));assertFalse(NormalIdleCancellationIdentity.eligible(s(8,5,4,4,true,false,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER));}
 @Test void noCameraPublicationOrForeignLatestSerialCannotBorrowPositiveControl(){assertFalse(NormalIdleCancellationIdentity.eligible(s(8,5,0,0,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER));assertFalse(NormalIdleCancellationIdentity.eligible(s(8,5,5,4,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER));}
 @Test void foreignRequestOrSkippedEpochCannotBeNumericallyRebased(){assertFalse(NormalIdleCancellationIdentity.transition(before(),s(9,6,4,4,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_TICK));assertFalse(NormalIdleCancellationIdentity.transition(before(),s(10,5,4,4,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_TICK));}
 @Test void actualHardwareAttemptEvenNoEffectRefuses(){assertFalse(NormalIdleCancellationIdentity.transition(before(),s(9,5,4,4,true,true,true,true,new Object()),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_FRAME));}
 @Test void pauseAndReplacementOwnerRefuse(){assertFalse(NormalIdleCancellationIdentity.transition(before(),s(9,5,4,4,true,true,false,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_FRAME));assertFalse(NormalIdleCancellationIdentity.transition(before(),s(9,5,4,4,true,true,true,false,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_FRAME));}
 @Test void chainRequiresAnotherActualSingleCancelFromExactPriorEndpoint(){var first=s(9,5,4,4,true,true,true,true,hardware);assertTrue(NormalIdleCancellationIdentity.transition(before(),first,NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_TICK));assertTrue(NormalIdleCancellationIdentity.transition(first,s(10,5,4,4,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_FRAME));assertFalse(NormalIdleCancellationIdentity.transition(first,s(11,5,4,4,true,true,true,true,hardware),NormalIdleCancellationIdentity.Cause.ROOT_FINAL_NO_OWNER,NormalIdleCancellationIdentity.Site.BEFORE_FRAME));}
}
